import {ALL_HISTORY_EVENTS} from './history-catalog.js';
import {deterministicRiskRoll} from './risk-statistics.js';
import {policyFor,policyWeight,policyEffects,policyTargets,POLICY_EVENTS} from './policy-data.js';
import {END} from './data.js';
import {MARKET_ASSETS,MARKET_BY_ID,STOCK_IDS,MARKET_EVENTS,ALLOCATIONS} from './market-data.js';
import {moneyText} from './format.js';
const mi=m=>Number(m.slice(0,4))*12+Number(m.slice(5))-1;
const at=i=>`${Math.floor(i/12)}-${String(i%12+1).padStart(2,'0')}`;
const hash=t=>{let h=2166136261;for(const c of t)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0)/4294967295;};
const r=n=>Math.round(n),bound=n=>Math.max(.01,Math.min(1e9,n));
const fees=id=>MARKET_BY_ID[id].fee;
const seed=()=>({usd:1200,goldUSD:12.5,...Object.fromEntries(STOCK_IDS.map(id=>[id,50000]))});
const prices=raw=>({...Object.fromEntries(MARKET_ASSETS.map(a=>[a.id,a.id==='gold'?bound(raw.goldUSD*raw.usd):bound(raw[a.id])]))});
const CACHE=new Map();
function futureEvent(month,model){if(model==='balanced-v1'&&month>END&&Number(month.slice(5))%6===0){const sign=deterministicRiskRoll(731,month,'future-sign')<.5?-1:1;return {id:'future-'+month,month,date:month+'-01',future:true,source:'게임 가정',url:null,title:sign>0?'가상 사건 · 수요·공급의 변화':'가상 사건 · 수요 둔화·공급 회복',text:'가상 미래의 가격 충격입니다. 반대 방향의 변동도 적용하며 실제 미래를 예측하지 않습니다.',effects:{index:sign*.04,energy:sign*.08,usd:sign*.025,goldUSD:sign*.025,consumer:-sign*.02,travel:-sign*.03}};}if(month<=END||Number(month.slice(5))%6!==0)return null;const n=Math.floor(hash(month+'future')*3);const variants=[{title:'가상 사건 · 자금 경색',text:'가상의 신용 불안이 나타났습니다. 실제 미래 사건이 아닌 게임 시나리오입니다.',effects:{index:-.08,finance:-.12,software:-.08,usd:.05,goldUSD:.04},deposit:.036},{title:'가상 사건 · 새로운 수요',text:'가상의 기술·서비스 수요가 늘어났습니다. 실제 미래를 예측하지 않습니다.',effects:{software:.10,chip:.07,index:.03,consumer:.025},deposit:.025},{title:'가상 사건 · 에너지 공급 차질',text:'게임에서 가정한 공급 차질로 테마별 영향이 달라집니다.',effects:{energy:.10,travel:-.07,consumer:-.03,usd:.025,goldUSD:.02},inflation:.04}];return {id:'future-'+month,month,date:month+'-01',future:true,source:'게임 가정',url:null,...variants[n]};}
export function eventsFor(month,model,edition){return [...ALL_HISTORY_EVENTS.filter(e=>e.month===month&&(!e.educationOnly||(edition||0)>=(e.edition||1))),...(futureEvent(month,model)?[futureEvent(month,model)]:[])];}
function drift(raw,month,policy=null,model){for(const key of Object.keys(raw)){const vol=key==='usd'?.012:key==='goldUSD'?.025:key==='index'?.024:.045;const annual=key==='usd'?.002:key==='goldUSD'?.035:.04;raw[key]=bound(raw[key]*Math.pow(1+annual,1/12)*(1+((model==='balanced-v1'?deterministicRiskRoll(419,month,key):hash(month+key))-.5)*vol*2*(key==='usd'?1+((policy?.fxSensitivity||1)-1)*policyWeight(policy,month):1)));}policyEffects(raw,policy,month);}
function effect(raw,e){for(const [key,value] of Object.entries(e.effects))raw[key]=bound(raw[key]*(1+value));}
export function snapshot(month,model,edition){const cacheKey=(model||'legacy')+(edition||0)+month;if(CACHE.has(cacheKey))return structuredClone(CACHE.get(cacheKey));let raw=seed(),deposit=.025,house=.025,inflation=.025;for(let i=mi('2002-12');i<=mi(month);i++){const m=at(i);if(i>mi('2002-12')){const p=model==='balanced-v1'&&m>END?null:policyFor(at(i-1)),target=policyTargets(p,m);drift(raw,m,p,model);deposit=target.deposit+(deposit-target.deposit)*.98;house=.025+(house-.025)*.97;inflation=target.inflation+(inflation-target.inflation)*.98;}for(const e of eventsFor(m,model,edition)){effect(raw,e);deposit=e.deposit??deposit;house=e.house??house;inflation=e.inflation??inflation;}}const x={raw,prices:prices(raw),deposit,house,inflation,policy:model==='balanced-v1'&&month>END?null:policyFor(month)};CACHE.set(cacheKey,x);return structuredClone(x);}
export function setMarketLifeEvents(s,enabled){if(!s.market||s.ended)throw Error('진행 중인 경제 시장에서 바꿀 수 있어요.');if(typeof enabled!=='boolean')throw Error('진행 방식을 확인해 주세요.');s.market.lifeEvents=enabled;}
export function marketValue(s){return s.market?MARKET_ASSETS.reduce((sum,a)=>sum+r((s.market.holdings[a.id]?.units||0)*s.market.prices[a.id]),0):0;}
export function marketRates(s){return s.market?{deposit:s.market.deposit,house:s.market.house,inflation:s.market.inflation}:null;}
export function initializeMarket(s,allocation='cash'){if(s.market)return;const model=s.household?'balanced-v1':undefined,x=snapshot(s.month,model,s.historyEdition);s.market={version:1,...(s.historyEdition?{historyEdition:s.historyEdition}:{}),...(model?{model}:{}),lifeEvents:true,month:s.month,...x,holdings:{},history:[{month:s.month,prices:{...x.prices}}],reports:[],notices:[],acknowledged:[],trades:[],startAllocation:allocation};
 if(s.stocks>0){s.market.holdings.index={units:s.stocks/x.prices.index,basis:s.stocks};s.stocks=0;}
 const plan=ALLOCATIONS.find(p=>p.id===allocation);if(!plan)throw Error('시작 자산 배분을 확인해 주세요.');const initial=s.cash;for(const [id,fraction] of Object.entries(plan.weights)){const amount=r(initial*fraction);if(id==='deposit'){s.cash-=amount;s.deposit+=amount;}else if(amount>=10000)trade(s,id,'buy',amount);}
 s.market.initialFees=s.market.trades.reduce((n,t)=>n+t.fee,0);
 s.log.push({id:s.log.length+1,month:s.month,type:'action',title:'경제 시뮬레이션 시장이 열렸다',text:`${plan.name}. 현금·예금·달러·금·테마 주식을 사용할 수 있습니다. 환율·주가·가격·예금금리는 모두 게임 모형이며 실제 시세가 아닙니다. 시작 배분의 매매 수수료도 차감합니다.`});}
export function quoteTrade(s,id,side,amount,all=false){if(!s.market)throw Error('경제 시장을 먼저 열어 주세요.');if((all&&side!=='sell')||!MARKET_BY_ID[id]||!['buy','sell'].includes(side))throw Error('매매 대상을 확인해 주세요.');if(!all&&(!Number.isSafeInteger(amount)||amount<10000||amount>1e12))throw Error('매매 금액은 10,000~1,000,000,000,000원 사이의 정수여야 합니다.');const price=s.market.prices[id],holding=s.market.holdings[id]||{units:0,basis:0};let units,gross,fee,cash;
 if(side==='buy'){units=Math.floor(amount/(1+fees(id))/price*1e6)/1e6;gross=r(units*price);fee=r(gross*fees(id));while(gross+fee>amount&&units>0){units=Math.max(0,units-.000001);gross=r(units*price);fee=r(gross*fees(id));}cash=gross+fee;}
 else{units=all?holding.units:Math.min(holding.units,Math.floor(amount/price*1e6)/1e6);gross=r(units*price);fee=r(gross*fees(id));cash=gross-fee;}
 let reason='';if(s.startMode==='birth'&&s.startAge+Math.floor((mi(s.month)-mi(s.start))/12)<19)reason='어린 시절에는 가족 가계를 관찰합니다. 직접 거래는 19세부터 열립니다.';else if(s.ended)reason='이미 마친 삶입니다.';else if(units<=0||gross<=0)reason=side==='buy'?'매수할 수량이 부족합니다.':'매도할 보유 수량이 없습니다.';else if(side==='buy'&&s.cash<cash)reason='사용 가능한 현금이 부족합니다.';return {id,side,price,units,gross,fee,cash,disabled:Boolean(reason),reason};}
export function trade(s,id,side,amount,all=false){const q=quoteTrade(s,id,side,amount,all);if(q.disabled)throw Error(q.reason);const m=s.market,h=m.holdings[id]||{units:0,basis:0};let realized=0;if(side==='buy'){s.cash-=q.cash;h.units+=q.units;h.basis+=q.cash;}else{const basis=q.units>=h.units?h.basis:r(h.basis*q.units/h.units);s.cash+=q.cash;h.units=Math.max(0,h.units-q.units);h.basis=Math.max(0,h.basis-basis);if(h.units<1e-10){h.units=0;h.basis=0;}realized=q.cash-basis;}m.holdings[id]=h;m.trades.push({month:s.month,id,side,units:q.units,gross:q.gross,fee:q.fee,realized});s.log.push({id:s.log.length+1,month:s.month,type:'action',title:MARKET_BY_ID[id].name+(side==='buy'?' 매수':' 매도'),text:`${q.units.toLocaleString('ko-KR',{maximumFractionDigits:6})}${MARKET_BY_ID[id].unit}. ${side==='buy'?'투입':'회수'} ${moneyText(q.cash)}. 수수료 ${moneyText(q.fee)}.${side==='sell'?' 실현손익 '+moneyText(realized)+'.':''} 모형 가격이며 세금은 미반영입니다.`});return q;}
export function sellHalfThemes(s){for(const id of STOCK_IDS){const units=s.market.holdings[id]?.units||0;if(units>0){const amount=r(units*s.market.prices[id]/2);if(amount>=10000)trade(s,id,'sell',amount);}}}
export function stepMarket(s){if(!s.market)return;const m=s.market;if(m.month===s.month)return;if(mi(s.month)!==mi(m.month)+1)throw Error('시장은 한 달씩 진행해야 합니다.');const active=m.model==='balanced-v1'&&s.month>END?null:policyFor(m.month),target=policyTargets(active,s.month);drift(m.raw,s.month,active,m.model);m.deposit=target.deposit+(m.deposit-target.deposit)*.98;m.house=.025+(m.house-.025)*.97;m.inflation=target.inflation+(m.inflation-target.inflation)*.98;for(const e of eventsFor(s.month,m.model,m.historyEdition)){const before=prices(m.raw),valueBefore=MARKET_ASSETS.reduce((n,a)=>n+r((m.holdings[a.id]?.units||0)*before[a.id]),0);effect(m.raw,e);const after=prices(m.raw),changes=Object.fromEntries(MARKET_ASSETS.map(a=>[a.id,r((m.holdings[a.id]?.units||0)*(after[a.id]-before[a.id]))]));const report={id:e.id,month:s.month,future:Boolean(e.future),delta:MARKET_ASSETS.reduce((n,a)=>n+r((m.holdings[a.id]?.units||0)*after[a.id]),0)-valueBefore,changes,before,after};m.reports.push(report);m.notices.push(e.id);m.deposit=e.deposit??m.deposit;m.house=e.house??m.house;m.inflation=e.inflation??m.inflation;s.log.push({id:s.log.length+1,month:s.month,type:'news',title:e.title,text:`${e.text} 내 금융 보유 자산의 사건 효과 ${moneyText(report.delta)}. 월 기본 변동·생활비·이자는 별도입니다. ${e.educationOnly?'이 학습 카드는 인위적인 가격 충격·개별 피해액을 부과하지 않습니다.':'효과의 방향과 수치는 게임 가정입니다.'}`});}m.month=s.month;m.policy=m.model==='balanced-v1'&&s.month>END?null:policyFor(s.month);m.prices=prices(m.raw);m.history.push({month:s.month,prices:{...m.prices}});}
export function reportFor(s,id){return s.market?.reports.findLast(r=>r.id===id)||null;}
export function economicEvent(s){const id=s.market?.notices[0];if(!id)return null;const e=ALL_HISTORY_EVENTS.find(e=>e.id===id)||eventsFor(s.month,s.market?.model,s.market?.historyEdition).find(e=>e.id===id);if(!e)return null;return {id:e.id,economicId:e.id,kind:'economic',category:e.future?'가상 시장 사건':e.policy?'정부·정책':'경제',title:e.title,text:e.text,date:e.date,source:e.source,url:e.url,future:Boolean(e.future)};}
export function acknowledgeEconomic(s,id){if(!s.market||!id)return;s.market.notices=s.market.notices.filter(x=>x!==id);if(!s.market.acknowledged.includes(id))s.market.acknowledged.push(id);}
export function validMarket(s){const m=s.market;if(m===undefined)return true;const validPrices=p=>p&&MARKET_ASSETS.every(a=>Number.isFinite(p[a.id])&&p[a.id]>0&&p[a.id]<=1e9);const known=id=>ALL_HISTORY_EVENTS.some(e=>e.id===id)||/^future-\d{4}-(06|12)$/.test(id);if(s.stocks!==0||(m.domesticEconomy!==undefined&&typeof m.domesticEconomy!=='boolean')||(m.lifeEvents!==undefined&&typeof m.lifeEvents!=='boolean'))return false;if(!m||m.historyEdition!==undefined&&![1,2,3,4,5,6].includes(m.historyEdition)||m.model!==undefined&&m.model!=='balanced-v1'||m.version!==1||m.month!==s.month||!validPrices(m.prices)||!m.raw||!['usd','goldUSD',...STOCK_IDS].every(id=>Number.isFinite(m.raw[id])&&m.raw[id]>0&&m.raw[id]<=1e9)||!ALLOCATIONS.some(p=>p.id===m.startAllocation))return false;
 if(m.initialFees!==undefined&&(!Number.isFinite(m.initialFees)||m.initialFees<0||m.initialFees>1e15))return false;
 for(const key of ['deposit','house','inflation'])if(!Number.isFinite(m[key])||m[key]<-.5||m[key]>.5)return false;
 if(!m.holdings||typeof m.holdings!=='object'||!Object.entries(m.holdings).every(([id,h])=>MARKET_BY_ID[id]&&h&&Number.isFinite(h.units)&&h.units>=0&&h.units<=1e15&&Number.isFinite(h.basis)&&h.basis>=0&&h.basis<=1e15))return false;
 if(!Array.isArray(m.history)||m.history.length<1||m.history.length>1500||m.history.at(-1)?.month!==s.month||!m.history.every((h,i)=>h&&typeof h.month==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(h.month)&&h.month>=s.start&&h.month<=s.month&&(!i||h.month>m.history[i-1].month)&&validPrices(h.prices)))return false;
 for(const key of ['notices','acknowledged'])if(!Array.isArray(m[key])||m[key].length>1500||!m[key].every(known)||new Set(m[key]).size!==m[key].length)return false;
 if(!Array.isArray(m.reports)||m.reports.length>1500||!m.reports.every(r=>r&&known(r.id)&&typeof r.month==='string'&&Number.isFinite(r.delta)&&r.changes&&MARKET_ASSETS.every(a=>Number.isFinite(r.changes[a.id]))&&validPrices(r.before)&&validPrices(r.after)))return false;
 return Array.isArray(m.trades)&&m.trades.length<=10000&&m.trades.every(t=>t&&MARKET_BY_ID[t.id]&&['buy','sell'].includes(t.side)&&typeof t.month==='string'&&['units','gross','fee','realized'].every(k=>Number.isFinite(t[k]))&&t.units>0&&t.gross>=0&&t.fee>=0);}
